using System; using System.Collections.Generic;
namespace SuijinMaterials.Merchants { public sealed class MerchantStockInstaller { private readonly IMerchantStockFacade facade;private readonly Action<string> log;private readonly List<object> owned=new List<object>();public MerchantStockInstaller(IMerchantStockFacade facade,Action<string> log){this.facade=facade;this.log=log??(_=>{});}public MerchantInstallationSummary Install(MerchantStockSettings settings){Uninstall();int ok=0,off=0,fail=0;foreach(var d in MerchantStockCatalog.All){var s=settings.Get(d.ListingId);if(!s.Enabled){off++;continue;}try{owned.Add(facade.Add(d,s));ok++;}catch(Exception e){fail++;log("Merchant listing '"+d.ListingId+"' failed: "+e.Message);}}return new MerchantInstallationSummary(ok,off,fail);}public void Uninstall(){foreach(var h in owned)try{facade.Remove(h);}catch(Exception e){log("Merchant removal failed: "+e.Message);}owned.Clear();} } }
